 Begin CmpMap 	# Compound Mapping
    Nin = 1 	# Number of input coordinates
    ReSimp = 1 	# Simplify restricted to allowed Mappings
 IsA Mapping 	# Mapping between coordinate systems
    MapA = 	# First component Mapping
       Begin CmpMap 	# Compound Mapping
          Nin = 1 	# Number of input coordinates
       IsA Mapping 	# Mapping between coordinate systems
          MapA = 	# First component Mapping
             Begin ZoomMap 	# Zoom about the origin
                Nin = 1 	# Number of input coordinates
                AlSimp = 1 	# Will be used by restricted Simplify
             IsA Mapping 	# Mapping between coordinate systems
                Zoom = 2 	# Zoom factor
             End ZoomMap
          MapB = 	# Second component Mapping
             Begin ZoomMap 	# Zoom about the origin
                Nin = 1 	# Number of input coordinates
                AlSimp = 1 	# Will be used by restricted Simplify
             IsA Mapping 	# Mapping between coordinate systems
                Zoom = 3 	# Zoom factor
             End ZoomMap
       End CmpMap
    MapB = 	# Second component Mapping
       Begin CmpMap 	# Compound Mapping
          Nin = 1 	# Number of input coordinates
       IsA Mapping 	# Mapping between coordinate systems
          MapA = 	# First component Mapping
             Begin MathMap 	# Transformation using mathematical functions
                Nin = 1 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
                Fwd1 = "y=2*x" 	# Forward function 1
                Inv1 = "x=0.5*y" 	# Inverse function 1
             End MathMap
          MapB = 	# Second component Mapping
             Begin ZoomMap 	# Zoom about the origin
                Nin = 1 	# Number of input coordinates
                AlSimp = 1 	# Will be used by restricted Simplify
             IsA Mapping 	# Mapping between coordinate systems
                Zoom = 7 	# Zoom factor
             End ZoomMap
       End CmpMap
 End CmpMap
